class Bad:
    n: int

def check(x: int) -> int fail Bad:
    if x % 2 == 1:
        fail Bad(n=x)
    return x

def all_even(xs: list[int]) -> list[int] fail Bad:
    """Check every element of xs in parallel. Returns xs when all are even, otherwise fails with the Bad of the lowest-index odd element, regardless of which thread finishes first."""
    post out == xs
    ex all_even([2, 4, 6]) == Ok([2, 4, 6])
    ex all_even([]) == Ok([])
    ex all_even([2, 3, 5]) == Err(Bad(n=3))
    ex all_even([7, 4, 9]) == Err(Bad(n=7))
    results = par [check(x) else -1 for x in xs]
    for i in range(results.len()):
        if results[i] < 0:
            fail Bad(n=xs[i])
    return xs.copy()

